/**
 * Client-side autonomous-vehicle fleet simulation.
 *
 * Vehicles drive along predefined San-Francisco routes, interpolating between
 * waypoints. Each tick advances them by distance = speed × dt, updates heading,
 * drains battery, and appends to a capped trail (the "path tracing"). No backend
 * needed -- it's a self-contained visualization driven by requestAnimationFrame.
 */

export type LatLng = [number, number];

export interface Vehicle {
  id: string;
  name: string;
  routeId: number;
  seg: number;
  t: number; // 0..1 along current segment
  pos: LatLng;
  heading: number; // degrees
  speedKph: number;
  battery: number; // 0..100
  status: "en route" | "charging";
  trail: LatLng[];
  label: string; // car / truck / bus / robotaxi
}

export const SF_CENTER: LatLng = [37.7749, -122.4194];
const TRAIL_LEN = 90; // dense road geometry covers less ground per point -> longer trail

