export const ROUTE_GEOMETRY_SOURCE = "osrm";
// PREFETCH:END

/** The routes the simulation drives (real roads when baked, else straight). */
export const ROUTES = ROUTE_GEOMETRY;

const VEHICLE_TYPES = ["robotaxi", "car", "truck", "bus"];
let _counter = 0;

function haversine(a: LatLng, b: LatLng): number {
  const R = 6371000;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLng = ((b[1] - a[1]) * Math.PI) / 180;
  const la1 = (a[0] * Math.PI) / 180;
  const la2 = (b[0] * Math.PI) / 180;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(la1) * Math.cos(la2) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function bearing(a: LatLng, b: LatLng): number {
  const dLng = ((b[1] - a[1]) * Math.PI) / 180;
  const la1 = (a[0] * Math.PI) / 180;
  const la2 = (b[0] * Math.PI) / 180;
  const y = Math.sin(dLng) * Math.cos(la2);
  const x = Math.cos(la1) * Math.sin(la2) - Math.sin(la1) * Math.cos(la2) * Math.cos(dLng);
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
}

function lerp(a: LatLng, b: LatLng, t: number): LatLng {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

export function spawnVehicle(label?: string, routeId?: number): Vehicle {
  _counter += 1;
  const rid = routeId ?? _counter % ROUTES.length;
  const route = ROUTES[rid];
  const seg = _counter % (route.length - 1);
  const pos = route[seg];
  return {
    id: `AV-${String(_counter).padStart(3, "0")}`,
    name: `AV-${String(_counter).padStart(3, "0")}`,
    routeId: rid,
    seg,
    t: 0,
    pos,
    heading: bearing(route[seg], route[seg + 1]),
    speedKph: 28 + (_counter % 5) * 6,
    battery: 60 + (_counter % 4) * 10,
    status: "en route",
    trail: [pos],
    label: label ?? VEHICLE_TYPES[_counter % VEHICLE_TYPES.length],
  };
}

/** Advance one vehicle by ``dt`` seconds (pure -- returns a new Vehicle). */
export function stepVehicle(v: Vehicle, dt: number): Vehicle {
  const route = ROUTES[v.routeId];
  let { seg, t, battery } = v;
  const charging = v.status === "charging";

  // Battery: drain while driving, recharge when low.
  battery += charging ? 14 * dt : -0.7 * dt;
  let status: Vehicle["status"] = v.status;
  if (battery <= 8) status = "charging";
  if (battery >= 95) status = "en route";
  battery = Math.max(0, Math.min(100, battery));

  const speed = status === "charging" ? v.speedKph * 0.15 : v.speedKph;
  let remaining = (speed * 1000) / 3600 * dt; // meters to move this tick

  // Walk forward across segments until we've consumed the distance.
  // Guard is high because real-road geometry has many short (~10-15 m) segments
  // and a fast vehicle at high time-scale can cross dozens per tick.
  for (let guard = 0; guard < 512 && remaining > 0; guard++) {
    const a = route[seg];
    const b = route[seg + 1];
    const segLen = Math.max(1, haversine(a, b));
    const distOnSeg = (1 - t) * segLen;
    if (remaining < distOnSeg) {
      t += remaining / segLen;
      remaining = 0;
    } else {
      remaining -= distOnSeg;
      seg = (seg + 1) % (route.length - 1);
      t = 0;
    }
  }

  const a = route[seg];
  const b = route[seg + 1];
  const pos = lerp(a, b, t);
  const trail = [...v.trail, pos].slice(-TRAIL_LEN);
  return { ...v, seg, t, pos, heading: bearing(a, b), battery, status, trail };
}

/** Vehicle-class labels YOLO produces that map onto the fleet. */
export const VEHICLE_CLASSES = new Set(["car", "truck", "bus", "motorcycle", "bicycle"]);

// --------------------------------------------------------------------------- #
// OSRM real-road routing (free public demo server, no key).                    #
// All coordinate swapping goes through these two helpers in ONE place: OSRM    #
// speaks [lng,lat]; the app speaks [lat,lng]. (Getting this wrong drops the    #
// vehicles in the ocean off Africa.) Used by the build-time prefetch script    #
// and by the runtime A->B route planner.                                       #
// --------------------------------------------------------------------------- #
const OSRM_BASE = "https://router.project-osrm.org/route/v1/driving";

export function osrmUrl(waypoints: LatLng[]): string {
  const coords = waypoints.map(([lat, lng]) => `${lng},${lat}`).join(";");
  return `${OSRM_BASE}/${coords}?overview=full&geometries=geojson&steps=false`;
}

export function osrmToLatLngs(data: unknown): LatLng[] {
  const d = data as { code?: string; routes?: { geometry: { coordinates: [number, number][] } }[] };
  if (d.code !== "Ok" || !d.routes?.length) throw new Error(`OSRM ${d.code ?? "no route"}`);
  return d.routes[0].geometry.coordinates.map(([lng, lat]) => [lat, lng] as LatLng);
}

/**
 * Plan a real-road route A -> B at runtime (for the interactive planner).
 * Returns the road polyline, or null on any failure/timeout (never throws),
 * so the caller falls back to a straight line and the UI never hangs.
 */
export async function planRoute(a: LatLng, b: LatLng, timeoutMs = 8000): Promise<LatLng[] | null> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(osrmUrl([a, b]), { signal: ctrl.signal });
    if (!res.ok) return null;
    return osrmToLatLngs(await res.json());
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// --------------------------------------------------------------------------- #
// Multi-stop trip planning (A -> B -> C -> ...) with real distance + drive time.
// OSRM returns the full road geometry, a total distance/duration, and a per-leg
// breakdown. ETA is a road-speed estimate (no live traffic — that needs a paid
// API), i.e. a "typical" drive time.
// --------------------------------------------------------------------------- #
export interface RouteLeg {
  distanceM: number;
  durationS: number;
}

export interface RoutePlan {
  geometry: LatLng[];
  distanceM: number;
  durationS: number;
  legs: RouteLeg[];
}

interface OsrmRoute {
  distance: number;
  duration: number;
  geometry: { coordinates: [number, number][] };
  legs?: { distance: number; duration: number }[];
}

/** Route through 2+ ordered stops. Returns geometry + totals + legs, or null. */
export async function routeThrough(stops: LatLng[], timeoutMs = 12000): Promise<RoutePlan | null> {
  if (stops.length < 2) return null;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(osrmUrl(stops), { signal: ctrl.signal });
    if (!res.ok) return null;
    const d = (await res.json()) as { code?: string; routes?: OsrmRoute[] };
    if (d.code !== "Ok" || !d.routes?.length) return null;
    const r = d.routes[0];
    return {
      geometry: r.geometry.coordinates.map(([lng, lat]) => [lat, lng] as LatLng),
      distanceM: r.distance,
      durationS: r.duration,
      legs: (r.legs ?? []).map((l) => ({ distanceM: l.distance, durationS: l.duration })),
    };
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

export function formatKm(meters: number): string {
  return meters >= 1000 ? `${(meters / 1000).toFixed(1)} km` : `${Math.round(meters)} m`;
}

export function formatEta(seconds: number): string {
  const min = Math.round(seconds / 60);
  if (min < 1) return "<1 min";
  if (min < 60) return `${min} min`;
  const h = Math.floor(min / 60);
  return `${h} h ${min % 60} min`;
}
